  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly or implicitly takes personal responsibility for a specific action, achievement, or outcome, often highlighting their role in securing funding, passing legislation, or advocating for a cause.",
    "clarification": "Credit-claiming is identified when a senator uses language such as 'I secured,' 'I helped,' 'I announced,' 'I authored,' or similar phrases that directly link the senator to a positive outcome or action. This includes taking credit for funding, legislative achievements, or advocacy efforts that resulted in tangible benefits for their constituents or the nation. The focus is on the senator's personal involvement and the explicit or implicit attribution of success to their efforts.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states that he authored legislation that led to Bismarck State College being designated as a National Power Plant Operations Technology and Educational Center. This is a clear example of credit-claiming, as he directly links his legislative work to the college's achievement."
      },
      {
        "document_id": "3482",
        "explanation": "Sens. Mikulski and Cardin announce federal funding for firefighters and explicitly state Senator Mikulski's role on the Homeland Security Appropriations Subcommittee, which funds the program. This directly attributes the funding to her efforts."
      },
      {
        "document_id": "1747",
        "explanation": "Senator Byrd takes credit for creating the National Guard Youth ChalleNGe program in 1991 and securing legislation to increase federal funding for it. This is a clear case of credit-claiming, as he highlights his long-term involvement and legislative success."
      }
    ],
    "negative_clarification": "Credit-claiming does NOT occur when a senator discusses general issues, criticizes others, or expresses opinions without linking themselves to a specific action or outcome. Statements that are purely informational, critical, or advocacy-based without explicit or implicit personal attribution do not qualify as credit-claiming. Additionally, if a senator mentions a general role (e.g., being a member of a committee) without tying it to a specific achievement, it is not considered credit-claiming.",
    "negative_examples": [
